//  SPDX-License-Identifier: GPL-3.0-or-later
//  Copyright (C) 2019-2022, respective authors of MCFM.

//  Translated from W2jet/atree.f
//  Author: R.K. Ellis, July 1998.
//  The basic process is atreepp: amplitude for
//    q-(p4)+Q(-p2)+l-(-p5) --> q+(p1)+Q-(p3)+l+(p6)
//  All outgoing particles are right-handed, except Q(p3) which is left-handed.
//  All tree amplitudes divided by im wrt to BDKW paper.
//  Implementation of BDKW Eq.(3.10).

#include "atree.hpp"
#include <W1jet.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <complex>

using namespace mxpart_mod;
using namespace sprods_com_mod;

std::complex<double> atree(const char* st, int j1, int j2, int j3, int j4, int j5, int j6,
                           FArray2D<std::complex<double>>& za,
                           FArray2D<std::complex<double>>& zb) {

  // Statement function for pp (others derived by crossing)
  auto tree = [&za, &zb](int j1, int j2, int j3, int j4, int j5, int j6) -> std::complex<double> {
    return +zb(j1,j2)*za(j5,j4)*(za(j3,j1)*zb(j1,j6)+za(j3,j2)*zb(j2,j6))
                /(s(j2,j3)*s(j5,j6)*t(j1,j2,j3))
           +za(j3,j4)*zb(j6,j1)*(za(j5,j3)*zb(j3,j2)+za(j5,j4)*zb(j4,j2))
                /(s(j2,j3)*s(j5,j6)*t(j2,j3,j4));
  };

  std::complex<double> result(0.0, 0.0);

  if (st[0]=='p' && st[1]=='p') {
    result = +tree(j1,j2,j3,j4,j5,j6); // @coverage-probe
  } else if (st[0]=='p' && st[1]=='m') {
    result = -tree(j1,j3,j2,j4,j5,j6);
  } else if (st[0]=='s' && st[1]=='l') {
    // Not a real tree amplitude; auxiliary quantity
    result = -tree(j3,j1,j2,j4,j5,j6);
  }

  return result;
}

extern "C" {
  std::complex<double> atree_wrapper(const char* st, int j1, int j2, int j3, int j4, int j5, int j6,
                                     std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return atree(st, j1, j2, j3, j4, j5, j6, za, zb);
  }
}
